const KEY='wolinkup_portal_10';let db;try{db=JSON.parse(localStorage.getItem(KEY))||{users:[],session:null,orders:[],numbers:[],draft:{},reset:null}}catch(e){db={users:[],session:null,orders:[],numbers:[],draft:{},reset:null}};
