function notify(type,title,body,orderId=null){if(!db.session)return;db.notifications.push({id:'NT-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),userId:db.session,type,title,body,orderId,created:new Date().toISOString(),read:false});save()}
// V1.9: Clearly labeled, user-isolated sample notifications for offline demo only.
function seedDemoNotifications(){
  if(!db.session || db.sampleNoticeUsers?.includes(db.session))return;
  const examples=[
    ['payment','[Demo sample] Payment confirmed','Example: Your USD 10.00 payment was confirmed.'],
    ['payment','[Demo sample] Payment unsuccessful','Example: A payment attempt failed; retry from the associated order when available.'],
    ['topup','[Demo sample] Mobile top-up complete','Example: The recipient received the selected mobile credit.'],
    ['topup','[Demo sample] Top-up needs attention','Example: A recharge could not be completed; check the order for next steps.'],
    ['account','[Demo sample] New sign-in','Example: Your account was accessed. Review your account if this was unexpected.'],
    ['account','[Demo sample] Password updated','Example: Your account password was changed.']
  ];
  const base=Date.now();
  examples.forEach(([type,title,body],i)=>db.notifications.push({
    id:'SAMPLE-'+db.session+'-'+i,userId:db.session,type,title,body,
    orderId:null,created:new Date(base-i*60000).toISOString(),read:true,sample:true
  }));
  db.sampleNoticeUsers=[...(db.sampleNoticeUsers||[]),db.session];save();
}
const inbox=()=>db.notifications.filter(n=>n.userId===db.session).slice().reverse();
function notificationEvent(order,type,result){if(type==='payment') {const labels={success:'Payment confirmed',failed:'Payment failed',cancelled:'Payment cancelled',unknown:'Payment awaiting confirmation'};notify('payment',labels[result]||'Payment updated','Order '+order.id+' · '+money(order.total)+' USD. Payment status: '+result+'.',order.id)}else{notify('topup',result==='success'?'Top-up successful':'Top-up failed','Order '+order.id+' · '+order.dial+order.phone+'. Top-up status: '+result+'.',order.id)}}
