$('userArea').innerHTML=logged?`<div class="user-menu-anchor"><button type="button" class="user-chip user-menu-button" id="userMenuToggle" aria-haspopup="true" aria-expanded="false" title="${escape(user().email)}"><span class="user-avatar">${ico('user-round','user-avatar-icon')}</span></button><div class="user-menu" id="userMenu" hidden><a href="#/account">${ico('user-round')}${t('profile')}</a><a href="#/help">${ico('circle-help')}${t('help')}</a><button type="button" id="headerLogout">${ico('log-out')}${t('logout')}</button></div></div>`:`<a class="user-login" href="#/login">${ico('user-round')}${t('login')}</a>`;
